impl std::fmt::Debug for Icon {
    fn fmt(&self, formatter: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self.weight {
            IconWeight::Regular => self.name.fmt(formatter),
            weight => write!(formatter, "{:?}.{:?}", self.name, weight),
        }
    }
}

